def transform(grid):
    output = [row[:] for row in grid]

    # Find all cells with dynamic color (4)
    four_pos = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 4:
                four_pos.append((r, c))

    if not four_pos:
        return output

    # Sort by row to get head (topmost 4)
    four_pos_sorted = sorted(four_pos, key=lambda x: x[0])
    head_r, head_c = four_pos_sorted[0]

    # Determine input diagonal slope
    if len(four_pos_sorted) >= 2:
        r1, c1 = four_pos_sorted[0]
        r2, c2 = four_pos_sorted[1]
        if c2 > c1:
            diag_slope = 1   # Going down-right
        else:
            diag_slope = -1  # Going down-left

    # Trail 3s: opposite slope, starting at (head_r, head_c + 1)
    # Input slope +1 → Trail slope -1 (down-left)
    # Input slope -1 → Trail slope +1 (down-right)
    if diag_slope == 1:
        trail_r, trail_c = head_r, head_c + 1
        trail_slope = -1  # Down-left
    else:
        trail_r, trail_c = head_r, head_c + 1
        trail_slope = 1   # Down-right

    # Fill trail with 3s
    while trail_r < len(grid) and trail_c >= 0 and trail_c < len(grid[0]):
        output[trail_r][trail_c] = 3
        trail_r += 1
        trail_c += trail_slope

    # Keep original 4s in place
    for (r, c) in four_pos:
        output[r][c] = 4

    return output
